-- BhavAI schema. Postgres 15+ compatible (Supabase and embedded PGlite).
-- All identifiers are generated by the application, so no extensions are required.

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  name TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('SELLER', 'BUYER', 'ADMIN')),
  country TEXT NOT NULL DEFAULT 'IN',
  currency TEXT NOT NULL DEFAULT 'INR',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS sellers (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  business_name TEXT NOT NULL,
  country TEXT NOT NULL,
  currency TEXT NOT NULL,
  store_slug TEXT NOT NULL UNIQUE,
  description TEXT NOT NULL DEFAULT '',
  active BOOLEAN NOT NULL DEFAULT FALSE,
  onboarding_complete BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS buyers (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  company_name TEXT NOT NULL DEFAULT '',
  country TEXT NOT NULL,
  currency TEXT NOT NULL,
  preferences TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS products (
  id TEXT PRIMARY KEY,
  seller_id TEXT NOT NULL REFERENCES sellers(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  sku TEXT NOT NULL,
  category TEXT NOT NULL,
  images JSONB NOT NULL DEFAULT '[]'::jsonb,
  listed_price NUMERIC(12, 2) NOT NULL CHECK (listed_price > 0),
  currency TEXT NOT NULL,
  stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0),
  unit TEXT NOT NULL DEFAULT 'piece',
  country_of_origin TEXT NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (seller_id, sku)
);

CREATE TABLE IF NOT EXISTS seller_rules (
  id TEXT PRIMARY KEY,
  seller_id TEXT NOT NULL REFERENCES sellers(id) ON DELETE CASCADE,
  product_id TEXT NOT NULL UNIQUE REFERENCES products(id) ON DELETE CASCADE,
  floor_price NUMERIC(12, 2) NOT NULL CHECK (floor_price > 0),
  max_discount_percent NUMERIC(6, 2) NOT NULL CHECK (max_discount_percent >= 0 AND max_discount_percent <= 90),
  minimum_quantity INTEGER NOT NULL DEFAULT 1 CHECK (minimum_quantity >= 1),
  bulk_discounts JSONB NOT NULL DEFAULT '[]'::jsonb,
  max_rounds INTEGER NOT NULL DEFAULT 5 CHECK (max_rounds >= 1 AND max_rounds <= 12),
  auto_accept_threshold NUMERIC(12, 2),
  require_approval_below NUMERIC(12, 2),
  approval_required BOOLEAN NOT NULL DEFAULT FALSE,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS negotiations (
  id TEXT PRIMARY KEY,
  buyer_id TEXT NOT NULL REFERENCES buyers(id) ON DELETE CASCADE,
  seller_id TEXT NOT NULL REFERENCES sellers(id) ON DELETE CASCADE,
  product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'OPEN'
    CHECK (status IN ('OPEN', 'AWAITING_APPROVAL', 'AGREED', 'REJECTED', 'CANCELLED', 'EXPIRED')),
  requested_quantity INTEGER NOT NULL CHECK (requested_quantity > 0),
  currency TEXT NOT NULL,
  listed_price NUMERIC(12, 2) NOT NULL,
  budget_total NUMERIC(12, 2),
  market_type TEXT NOT NULL CHECK (market_type IN ('DOMESTIC', 'CROSS_BORDER')),
  rounds_used INTEGER NOT NULL DEFAULT 0,
  max_rounds INTEGER NOT NULL DEFAULT 5,
  agent_mode TEXT NOT NULL DEFAULT 'POLICY',
  last_actor TEXT,
  is_sample BOOLEAN NOT NULL DEFAULT FALSE,
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS offers (
  id TEXT PRIMARY KEY,
  negotiation_id TEXT NOT NULL REFERENCES negotiations(id) ON DELETE CASCADE,
  submitted_by TEXT NOT NULL CHECK (submitted_by IN ('BUYER_AGENT', 'SELLER_AGENT', 'BUYER', 'SELLER')),
  agent_type TEXT NOT NULL DEFAULT 'POLICY',
  unit_price NUMERIC(12, 2) NOT NULL,
  total_price NUMERIC(12, 2) NOT NULL,
  quantity INTEGER NOT NULL,
  validation_status TEXT NOT NULL
    CHECK (validation_status IN ('VALID', 'BELOW_MINIMUM', 'ABOVE_LISTED', 'QUANTITY_UNAVAILABLE', 'BELOW_MIN_QUANTITY', 'INVALID')),
  message TEXT NOT NULL DEFAULT '',
  explanation TEXT NOT NULL DEFAULT '',
  round INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS deals (
  id TEXT PRIMARY KEY,
  negotiation_id TEXT NOT NULL UNIQUE REFERENCES negotiations(id) ON DELETE CASCADE,
  agreed_unit_price NUMERIC(12, 2) NOT NULL,
  agreed_quantity INTEGER NOT NULL CHECK (agreed_quantity > 0),
  total_amount NUMERIC(12, 2) NOT NULL,
  currency TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'ACCEPTED'
    CHECK (status IN ('PENDING_APPROVAL', 'ACCEPTED', 'CANCELLED', 'CONSUMED')),
  market_type TEXT NOT NULL CHECK (market_type IN ('DOMESTIC', 'CROSS_BORDER')),
  is_sample BOOLEAN NOT NULL DEFAULT FALSE,
  accepted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS orders (
  id TEXT PRIMARY KEY,
  deal_id TEXT NOT NULL UNIQUE REFERENCES deals(id) ON DELETE CASCADE,
  seller_id TEXT NOT NULL REFERENCES sellers(id),
  buyer_id TEXT NOT NULL REFERENCES buyers(id),
  payment_provider TEXT NOT NULL CHECK (payment_provider IN ('PAYPAL', 'MANUAL')),
  external_order_id TEXT,
  market_type TEXT NOT NULL CHECK (market_type IN ('DOMESTIC', 'CROSS_BORDER')),
  status TEXT NOT NULL DEFAULT 'PENDING_PAYMENT'
    CHECK (status IN ('PENDING_PAYMENT', 'APPROVAL_PENDING', 'PAID', 'SETTLEMENT_PENDING', 'SETTLED', 'FULFILLED', 'CANCELLED', 'FAILED')),
  payment_state TEXT NOT NULL DEFAULT 'CREATED'
    CHECK (payment_state IN ('CREATED', 'APPROVAL_PENDING', 'APPROVED', 'CAPTURE_PENDING', 'COMPLETED', 'FAILED', 'CANCELLED')),
  total_amount NUMERIC(12, 2) NOT NULL,
  currency TEXT NOT NULL,
  settlement_note TEXT,
  is_sample BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS payments (
  id TEXT PRIMARY KEY,
  order_id TEXT NOT NULL UNIQUE REFERENCES orders(id) ON DELETE CASCADE,
  provider TEXT NOT NULL CHECK (provider IN ('PAYPAL', 'MANUAL')),
  provider_order_id TEXT,
  provider_capture_id TEXT,
  amount NUMERIC(12, 2) NOT NULL,
  currency TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'CREATED'
    CHECK (status IN ('CREATED', 'APPROVAL_PENDING', 'APPROVED', 'CAPTURE_PENDING', 'COMPLETED', 'FAILED', 'CANCELLED')),
  approval_url TEXT,
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS webhook_events (
  id TEXT PRIMARY KEY,
  provider TEXT NOT NULL,
  provider_event_id TEXT NOT NULL,
  event_type TEXT NOT NULL,
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  processed_at TIMESTAMPTZ,
  processing_status TEXT NOT NULL DEFAULT 'RECEIVED'
    CHECK (processing_status IN ('RECEIVED', 'PROCESSED', 'IGNORED', 'FAILED')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (provider, provider_event_id)
);

CREATE TABLE IF NOT EXISTS api_keys (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  label TEXT NOT NULL,
  key_hash TEXT NOT NULL UNIQUE,
  prefix TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('SELLER', 'BUYER', 'ADMIN')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_used_at TIMESTAMPTZ,
  revoked_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS password_resets (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TIMESTAMPTZ NOT NULL,
  used_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS audit_logs (
  id TEXT PRIMARY KEY,
  actor_id TEXT,
  actor_role TEXT,
  action TEXT NOT NULL,
  resource_type TEXT NOT NULL,
  resource_id TEXT,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_products_seller ON products(seller_id);
CREATE INDEX IF NOT EXISTS idx_products_active ON products(active);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category);
CREATE INDEX IF NOT EXISTS idx_negotiations_seller ON negotiations(seller_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_negotiations_buyer ON negotiations(buyer_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_offers_negotiation ON offers(negotiation_id, created_at ASC);
CREATE INDEX IF NOT EXISTS idx_orders_seller ON orders(seller_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_orders_buyer ON orders(buyer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_api_keys_hash ON api_keys(key_hash);

ALTER TABLE offers ADD COLUMN IF NOT EXISTS kind TEXT NOT NULL DEFAULT 'OFFER';
ALTER TABLE deals ADD COLUMN IF NOT EXISTS buyer_confirmed_at TIMESTAMPTZ;

ALTER TABLE sellers ADD COLUMN IF NOT EXISTS rules_confirmed BOOLEAN NOT NULL DEFAULT FALSE;
